      }
      for (var index = 0; index < 12; index += 1) {
        await tester.pump(const Duration(milliseconds: 16));
        closingCardTops.add(tester.getRect(cardFrame).top);
      }
      expect(
        editor,
        findsOneWidget,
        reason: 'The image picker owns keyboard dismissal inside the editor.',
      );
      for (final cardTop in closingCardTops) {
        expect(
          cardTop,
          closeTo(anchoredCardTop, 0.1),
          reason: 'The image picker must not move the role editor.',
        );
      }
      expect(tester.getRect(cardFrame).top, closeTo(anchoredCardTop, 0.1));
      expect(
        tester.getRect(inlineAvatarFinder).top,
        closeTo(avatarTopBeforePicker, 0.1),
        reason: 'Picker dismissal must preserve the editor inner offset.',
      );
      expect(
        tester.widget<TextField>(identityField).focusNode?.hasFocus,
        isTrue,
      );
      expect(tester.widget<TextField>(nameField).focusNode?.hasFocus, isFalse);
      expect(tester.testTextInput.isVisible, isTrue);
      _genesisKeyboardAnimationEventSink!.success(const <String, Object>{
        'generation': 3,
        'phase': 'opening',
        'startInset': 0.0,
        'endInset': 280.0,
        'durationMillis': 250.0,
      });
      for (final keyboardInset in <double>[80, 180, 280]) {
        tester.view.viewInsets = FakeViewPadding(bottom: keyboardInset);
        await tester.pump(const Duration(milliseconds: 20));
        expect(tester.getRect(cardFrame).top, closeTo(anchoredCardTop, 0.1));
        expect(
          tester.getRect(inlineAvatarFinder).top,
          closeTo(avatarTopBeforePicker, 0.1),
        );
      }
      for (var index = 0; index < 12; index += 1) {
        await tester.pump(const Duration(milliseconds: 16));
      }
      await tester.pumpAndSettle();
      expect(
        tester.widget<TextField>(identityField).focusNode?.hasFocus,
        isTrue,
      );
      expect(tester.getRect(cardFrame).top, closeTo(anchoredCardTop, 0.1));
      expect(
        tester.getRect(inlineAvatarFinder).top,
        closeTo(avatarTopBeforePicker, 0.1),
      );

      final editingCardRect = tester.getRect(cardFrame);
      await tester.tapAt(
        Offset(editingCardRect.left + 4, editingCardRect.center.dy),
      );
      await tester.pump();
      expect(
        editor,
        findsOneWidget,
        reason: 'Tapping blank space inside the card must not end editing.',
      );
      expect(
        tester.widget<TextField>(identityField).focusNode?.hasFocus,
        isTrue,
        reason: 'Tapping blank space inside the card must preserve focus.',
      );
      tester.widget<TextField>(identityField).focusNode?.unfocus();
      await tester.pump();
      _genesisKeyboardAnimationEventSink!.success(const <String, Object>{
        'generation': 4,
        'phase': 'closing',
        'startInset': 280.0,
        'endInset': 0.0,
        'durationMillis': 250.0,
      });
      final roleTitle = find.text('Select Your Role');
      final closingRoleTitleTops = <double>[tester.getTopLeft(roleTitle).dy];
      for (final keyboardInset in <double>[180, 24, 30, 12, 0]) {
        tester.view.viewInsets = FakeViewPadding(bottom: keyboardInset);
        await tester.pump(const Duration(milliseconds: 16));
        closingRoleTitleTops.add(tester.getTopLeft(roleTitle).dy);
      }
      for (var frame = 0; frame < 20; frame += 1) {
        await tester.pump(const Duration(milliseconds: 16));
        closingRoleTitleTops.add(tester.getTopLeft(roleTitle).dy);
      }
      final roleTitleTravel =
          closingRoleTitleTops.last - closingRoleTitleTops.first;
      for (var frame = 1; frame < closingRoleTitleTops.length; frame += 1) {
        final step =
            closingRoleTitleTops[frame] - closingRoleTitleTops[frame - 1];
        expect(
          roleTitleTravel >= 0 ? step : -step,
          greaterThanOrEqualTo(-1),
          reason:
              'Role-editor close frame $frame must not reverse from its '
              'established direction.',
        );
      }
      await tester.pumpAndSettle();
      expect(
        tester.widget<IgnorePointer>(composerVisibilityFinder).ignoring,
        isTrue,
        reason: 'Dismissing the keyboard must keep role editing active.',
      );
      expect(
        find.byKey(const ValueKey<String>('origin-expanded-opening-composer')),
        findsOneWidget,
      );
      expect(editor, findsOneWidget);
      final inlineEditorScroll = find.byKey(
        const ValueKey<String>(
          'origin-setup-role-inline-editor-scroll-current-user',
        ),
      );
      expect(
        tester.widget<SingleChildScrollView>(inlineEditorScroll).physics,
        isA<NeverScrollableScrollPhysics>(),
      );
      for (final field in tester.widgetList<TextField>(
        find.descendant(of: editor, matching: find.byType(TextField)),
      )) {
        expect(field.scrollPhysics, isA<NeverScrollableScrollPhysics>());
      }
      final inlineEditorScrollPosition = tester
          .state<ScrollableState>(
            find
                .descendant(
                  of: inlineEditorScroll,
                  matching: find.byType(Scrollable),
                )
                .first,
          )
          .position;
      final inlineEditorOffsetBeforeDrag = inlineEditorScrollPosition.pixels;
      await tester.drag(editor, const Offset(0, -32));
      await tester.pump();
      expect(
        editor,
        findsOneWidget,
        reason: 'Dragging inside the role card must not end editing.',
      );
      expect(
        inlineEditorScrollPosition.pixels,
        closeTo(inlineEditorOffsetBeforeDrag, 0.01),
        reason: 'The inline role editor must not scroll from user gestures.',
      );
      expect(
        tester.widget<TextField>(nameField).controller?.text,
        'Edited Profile',
      );
      // Reproduce a platform that keeps reporting a non-zero inset but never
      // sends the final keyboard-closing metrics callback.
      tester.view.viewInsets = const FakeViewPadding(bottom: 280);
      await tester.pump();
      tester
          .widget<TapRegion>(
            find.byKey(
              const ValueKey<String>(
                'origin-setup-role-tap-region-current-user',
              ),
            ),
          )
          .onTapOutside!(const PointerDownEvent(position: Offset.zero));
      await tester.pump();
      expect(
        editor,
        findsNothing,
        reason: 'Tapping outside must leave the role-card edit UI immediately.',
      );
      final openingSheetList = find.byKey(
        const PageStorageKey<String>('origin-detail-bottom-sheet-o_test_1'),
      );
      expect(
        tester.widget<CustomScrollView>(openingSheetList).physics,
        isA<NeverScrollableScrollPhysics>(),
        reason: 'The sheet stays locked only while the closing animation runs.',
      );
      await tester.pump(const Duration(milliseconds: 439));
      expect(
        tester.widget<CustomScrollView>(openingSheetList).physics,
        isA<NeverScrollableScrollPhysics>(),
      );
      await tester.pump(const Duration(milliseconds: 1));
      final fallbackClosingCardTops = <double>[tester.getRect(cardFrame).top];
      for (var frame = 0; frame < 30; frame += 1) {
        await tester.pump(const Duration(milliseconds: 16));
        fallbackClosingCardTops.add(tester.getRect(cardFrame).top);
        if (tester.widget<CustomScrollView>(openingSheetList).physics
            is ClampingScrollPhysics) {
          break;
        }
      }
      expect(
        tester.widget<CustomScrollView>(openingSheetList).physics,
        isA<ClampingScrollPhysics>(),
        reason:
            'A missing terminal IME frame must not leave sheet scrolling '
            'locked after the closing animation window.',
      );
      for (var index = 1; index < fallbackClosingCardTops.length; index += 1) {
        expect(
          (fallbackClosingCardTops[index] - fallbackClosingCardTops[index - 1])
              .abs(),
          lessThan(30),
          reason:
              'The fallback close must not expose the full paint-translation '
              'difference on any frame.',
        );
      }
      final alignedCardTop = tester.getRect(cardFrame).top;
      expect(
        alignedCardTop,
        closeTo(fallbackClosingCardTops.last, 0.1),
        reason:
            'The fallback animation endpoint and the ordinary list layout '
            'must already have the same coordinate.',
      );
      await tester.pump();
      expect(
        tester.getRect(cardFrame).top,
        closeTo(alignedCardTop, 0.1),
        reason:
            'Removing the paint correction must not move the real role-card '
            'layout on the following frame.',
      );
      tester.view.viewInsets = FakeViewPadding.zero;
      await tester.pumpAndSettle();
      expect(
        tester.widget<IgnorePointer>(composerVisibilityFinder).ignoring,
        isFalse,
      );
      expect(
        tester.widget<PageView>(roleCardsFinder).physics,
        isA<PageScrollPhysics>(),
      );
      expect(editor, findsNothing);
      expect(composerSpacer, findsOneWidget);
      expect(tester.getSize(composerSpacer).height, composerSpacerHeight);
      final restoredOpeningPosition = tester
          .state<ScrollableState>(
            find
                .descendant(
                  of: find.byKey(
                    const PageStorageKey<String>(
                      'origin-detail-bottom-sheet-o_test_1',
                    ),
                  ),
                  matching: find.byType(Scrollable),
                )
                .first,
          )
          .position;
      expect(
        restoredOpeningPosition.pixels,
        closeTo(restoredOpeningPosition.maxScrollExtent, 0.1),
      );
      final restoredOffsetBeforeVerticalDrag = restoredOpeningPosition.pixels;
      await tester.drag(openingSheetList, const Offset(0, 160));
      await tester.pumpAndSettle();
      expect(
        restoredOpeningPosition.pixels,
        lessThan(restoredOffsetBeforeVerticalDrag - 1),
        reason:
            'After the translation handoff, a real vertical drag must move '
            'the opening sheet instead of being cancelled by a stale '
            'ScrollPosition animation.',
      );
      restoredOpeningPosition.jumpTo(restoredOpeningPosition.maxScrollExtent);
      await tester.pumpAndSettle();
      final roleIndicator = find.byKey(
        const ValueKey<String>('origin-setup-role-page-indicator'),
      );
      final rolePill = find.byKey(
        const ValueKey<String>('origin-location-chat-role-pill'),
      );
      final rolePillLabel = find.descendant(
        of: rolePill,
        matching: find.byKey(
          const ValueKey<String>('origin-location-chat-role-label'),
        ),
      );
      expect(tester.widget<Text>(rolePillLabel).data, 'Profile Hero');
      expect(
        tester.getRect(rolePill).top - tester.getRect(roleIndicator).bottom,
        greaterThanOrEqualTo(16),
      );

      tester
          .widget<InkWell>(
            find.byKey(
              const ValueKey<String>('origin-setup-role-edit-current-user'),
            ),
          )
          .onTap!();
      await tester.pump();
      final reopenedNameField = find
          .descendant(
            of: find.byKey(
              const ValueKey<String>(
                'origin-setup-role-inline-editor-current-user',
              ),
            ),
            matching: find.byType(TextField),
          )
          .first;
      expect(
        tester.widget<TextField>(reopenedNameField).controller?.text,
        'Profile Hero',
        reason: 'Tapping outside cancels the draft and ends editing.',
      );
      await tester.enterText(reopenedNameField, 'Discarded by swipe');
      await tester.drag(roleCardsFinder, const Offset(-220, 0));
      await tester.pumpAndSettle();
      expect(
        editor,
        findsNothing,
        reason: 'A user role-card swipe must cancel editing.',
      );
      unawaited(
        roleCards.controller!.animateToPage(
          0,
          duration: const Duration(milliseconds: 260),
          curve: Curves.easeOutCubic,
        ),
      );
      await tester.pumpAndSettle();
      tester
          .widget<InkWell>(
            find.byKey(
              const ValueKey<String>('origin-setup-role-edit-current-user'),
            ),
          )
          .onTap!();
      await tester.pump();
      final nameAfterSwipeCancel = find
          .descendant(of: editor, matching: find.byType(TextField))
          .first;
      expect(
        tester.widget<TextField>(nameAfterSwipeCancel).controller?.text,
        'Profile Hero',
        reason: 'Cancelling by horizontal swipe must discard the draft.',
      );
      tester
          .widget<InkWell>(
            find.byKey(
              const ValueKey<String>('origin-setup-role-edit-current-user'),
            ),
          )
          .onTap!();
      await tester.pump();
      final terminalPaintedCardTop = tester.getRect(cardFrame).top;
      await tester.pumpAndSettle();
      expect(
        tester.getRect(cardFrame).top,
        closeTo(terminalPaintedCardTop, 0.1),
        reason:
            'The terminal paint frame and the ordinary role-card layout must '
            'share the same screen coordinate.',
      );
    },
  );

