      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetViewInsets);
      addTearDown(tester.view.resetPadding);
      addTearDown(tester.view.resetViewPadding);
      final dialogue = List<Map<String, Object?>>.generate(
        4,
        (index) => <String, Object?>{
          'char_id': 'c_o_test_1',
          'char_name': 'Detail Character',
          'content': 'Composer docking line $index',
        },
        growable: false,
      );
      final transport = _RecordingV1ListTransport(
        originTicks: <Map<String, Object?>>[
          <String, Object?>{
            'tick_no': 1,
            'tick_result': <String, Object?>{
              'location_groups': <Map<String, Object?>>[
                <String, Object?>{
                  'location_id': 'l_o_test_1',
                  'initial_dialogue': dialogue,
                },
              ],
            },
          },
        ],
      );
      await tester.pumpWidget(
        AppServicesScope(
          services: await _testServices(transport: transport, useMock: false),
          child: const MaterialApp(
            home: OriginWorldPage(
              oid: 'o_test_1',
              originId: 0,
              showOpeningSheetOnEntry: true,
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();

      final visibility = find.byKey(
        const ValueKey<String>('origin-expanded-opening-composer-visibility'),
      );
      final surface = find.byKey(
        const ValueKey<String>('origin-detail-sheet-surface'),
      );
      final composer = find.byKey(
        const ValueKey<String>('origin-expanded-opening-composer'),
      );
      final warmedOpeningList = find.byKey(
        const PageStorageKey<String>('origin-detail-bottom-sheet-o_test_1'),
      );
      final roleTitle = find.text('Select Your Role');
      expect(
        find.text('Composer docking line 3'),
        findsOneWidget,
        reason:
            'Stable idle warmup builds and paints the complete message column.',
      );
      final warmedRowElements = find
          .descendant(
            of: warmedOpeningList,
            matching: find.byType(ChatMessageRow, skipOffstage: false),
            skipOffstage: false,
          )
          .evaluate()
          .toList(growable: false);
      expect(warmedRowElements, hasLength(5));
      expect(tester.widget<IgnorePointer>(visibility).ignoring, isFalse);
      expect(
        tester.getBottomLeft(surface).dy - tester.getBottomLeft(composer).dy,
        closeTo(0, 1),
      );
      for (var frame = 0; frame < 6; frame += 1) {
        await tester.pump(const Duration(milliseconds: 16));
        expect(composer, findsOneWidget);
        expect(
          tester.getBottomLeft(surface).dy - tester.getBottomLeft(composer).dy,
          closeTo(0, 1),
          reason: 'The docked composer must not oscillate between two layouts.',
        );
      }
      final normalOpeningList = find.byKey(
        const PageStorageKey<String>('origin-detail-bottom-sheet-o_test_1'),
      );
      final normalOpeningScrollable = find.descendant(
        of: normalOpeningList,
        matching: find.byType(Scrollable),
      );
      final normalOpeningPosition = tester
          .state<ScrollableState>(normalOpeningScrollable.first)
          .position;
      normalOpeningPosition.jumpTo(normalOpeningPosition.maxScrollExtent);
      await tester.pump();
      expect(normalOpeningPosition.pixels, greaterThan(0));

      final normalRows = find.descendant(
        of: normalOpeningList,
        matching: find.byType(ChatMessageRow),
      );
      final normalFlowContentGap =
          tester
              .getTopLeft(
                find.byKey(
                  const ValueKey<String>('origin-opening-role-section'),
                ),
              )
              .dy -
          tester.getBottomLeft(normalRows.last).dy;
      expect(normalFlowContentGap, greaterThan(0));
      late Key visibleMessageKey;
      late double visibleMessageTop;
      var foundVisibleMessage = false;
      final visibleContentTop = tester.getTopLeft(surface).dy;
      final visibleContentBottom = tester.getTopLeft(composer).dy;
      for (var index = 0; index < normalRows.evaluate().length; index += 1) {
        final candidate = normalRows.at(index);
        final rect = tester.getRect(candidate);
        if (rect.bottom <= visibleContentTop ||
            rect.top >= visibleContentBottom) {
          continue;
        }
        visibleMessageKey = tester.widget<ChatMessageRow>(candidate).key!;
        visibleMessageTop = rect.top;
        foundVisibleMessage = true;
        break;
      }
      expect(foundVisibleMessage, isTrue);
      final composerTopBeforeFocus = tester.getTopLeft(composer).dy;
      final composerHeightBeforeFocus = tester.getSize(composer).height;
      await tester.tap(
        find.descendant(
          of: composer,
          matching: find.byKey(const ValueKey<String>('chat-composer-input')),
        ),
      );
      await tester.pump();
      expect(
        tester
            .widget<EditableText>(
              find.descendant(
                of: composer,
                matching: find.byType(EditableText),
              ),
            )
            .focusNode
            .hasFocus,
        isTrue,
        reason: 'One tap keeps focus while the docked composer is prepared.',
      );
      for (var frame = 0; frame < 3; frame += 1) {
        final focusedAnchorMessage = find.descendant(
          of: normalOpeningList,
          matching: find.byKey(visibleMessageKey),
        );
        expect(focusedAnchorMessage, findsOneWidget);
        expect(
          tester.getTopLeft(focusedAnchorMessage).dy,
          closeTo(visibleMessageTop, 1),
          reason:
              'Keyboard preparation frame $frame must preserve the visible '
              'Opening Dialogue row.',
        );
        if (frame < 2) await tester.pump();
      }
      expect(
        tester.getTopLeft(composer).dy,
        closeTo(composerTopBeforeFocus, 0.1),
        reason:
            'Focus preparation must not move the composer before the native '
            'keyboard animation starts.',
      );
      expect(
        tester.getSize(composer).height,
        closeTo(composerHeightBeforeFocus, 0.1),
        reason: 'Focus preparation must keep the composer safe-area geometry.',
      );
      expect(_genesisKeyboardAnimationEventSink, isNotNull);
      _genesisKeyboardAnimationEventSink!.success(const <String, Object>{
        'generation': 1,
        'phase': 'opening',
        'startInset': 0.0,
        'endInset': 300.0,
        'durationMillis': 250.0,
      });
      await tester.pump();
      final keyboardOverlay = find.byKey(
        const ValueKey<String>('origin-opening-keyboard-message-overlay'),
      );
      expect(keyboardOverlay, findsNothing);
      expect(
        find.descendant(
          of: find.byKey(
            const ValueKey<String>('origin-detail-sheet-page-Opening'),
          ),
          matching: find.byType(CustomScrollView),
        ),
        findsOneWidget,
        reason: 'Keyboard focus must keep the original opening scroll view.',
      );
      final focusedAnchorMessage = find.descendant(
        of: normalOpeningList,
        matching: find.byKey(visibleMessageKey),
      );
      expect(focusedAnchorMessage, findsOneWidget);
      expect(
        tester.getTopLeft(focusedAnchorMessage).dy,
        closeTo(visibleMessageTop, 1),
        reason:
            'The original list must preserve the visible message position '
            'when keyboard preparation starts.',
      );
      expect(
        find.descendant(
          of: normalOpeningList,
          matching: find.text('Composer docking line 3'),
        ),
        findsOneWidget,
        reason:
            'Opening Dialogue keeps one stable eager layout before and during '
            'keyboard preparation.',
      );
      final openingViewportTop = tester.getTopLeft(normalOpeningList).dy;
      final contentTopBeforeKeyboardInset = tester
          .getTopLeft(focusedAnchorMessage)
          .dy;
      tester.view.viewInsets = const FakeViewPadding(bottom: 150);
      await tester.pump();
      expect(
        tester.getTopLeft(normalOpeningList).dy,
        closeTo(openingViewportTop, 0.1),
        reason:
            'Keyboard progress moves the sliver content, not the original '
            'viewport itself.',
      );
      final contentTopAtHalfKeyboardInset = tester
          .getTopLeft(focusedAnchorMessage)
          .dy;
      tester.view.viewInsets = const FakeViewPadding(bottom: 300);
      for (var frame = 0; frame < 12; frame += 1) {
        await tester.pump();
      }
      final contentTopAtFullKeyboardInset = tester
          .getTopLeft(focusedAnchorMessage)
          .dy;
      expect(
        contentTopAtHalfKeyboardInset,
        closeTo(
          (contentTopBeforeKeyboardInset + contentTopAtFullKeyboardInset) / 2,
          1,
        ),
        reason:
            'A native target received before focus must drive one continuous '
            'message animation without an intermediate overshoot.',
      );
      expect(
        tester.getBottomLeft(composer).dy -
            tester.view.viewPadding.bottom / tester.view.devicePixelRatio,
        closeTo(480, 1),
        reason:
            'The composer excluding its persistent safe area ends at the '
            'keyboard top.',
      );
      expect(
        tester.widget<CustomScrollView>(normalOpeningList).physics,
        isA<ClampingScrollPhysics>(),
        reason: 'The original message list becomes scrollable once open.',
      );
      final keyboardLayoutSpacer = find.byKey(
        const ValueKey<String>('origin-opening-keyboard-layout-spacer'),
        skipOffstage: false,
      );
      expect(keyboardLayoutSpacer, findsOneWidget);
      expect(
        tester.getSize(keyboardLayoutSpacer).height,
        closeTo(0, 0.1),
        reason:
            'The retained role section already provides enough scroll range, '
            'so the keyboard height must not be appended a second time.',
      );
      final focusedRows = find.descendant(
        of: normalOpeningList,
        matching: find.byType(ChatMessageRow, skipOffstage: false),
        skipOffstage: false,
      );
      final focusedRowElements = focusedRows.evaluate().toList(growable: false);
      expect(focusedRowElements.first, same(warmedRowElements.first));
      expect(focusedRowElements.last, same(warmedRowElements.last));
      final focusedGapFromBottomStart =
          tester.getTopLeft(composer).dy -
          tester.getBottomLeft(focusedRows.last).dy;
      expect(
        focusedGapFromBottomStart,
        closeTo(
          normalFlowContentGap -
              originOpeningKeyboardDialogueGapReductionForTesting,
          1,
        ),
        reason:
            'Focused layout keeps the message content 10px closer to the '
            'composer than the normal role-section flow gap.',
      );
      normalOpeningPosition.jumpTo(
        (normalOpeningPosition.pixels + 80)
            .clamp(
              normalOpeningPosition.minScrollExtent,
              normalOpeningPosition.maxScrollExtent,
            )
            .toDouble(),
      );
      await tester.pump();
      final focusedMessageTopBeforeClose = tester
          .getTopLeft(focusedAnchorMessage)
          .dy;
      final composerBottomLimit = tester.getBottomLeft(surface).dy;
      var previousComposerBottom = tester.getBottomLeft(composer).dy;
      var sawIntermediateClosingPosition = false;
      FocusManager.instance.primaryFocus?.unfocus();
      await tester.pump();
      expect(
        tester.getTopLeft(focusedAnchorMessage).dy,
        closeTo(focusedMessageTopBeforeClose, 0.1),
        reason:
            'The first focus loss must reserve its zero-keyboard range before '
            'the keyboard layout starts changing.',
      );
      tester.view.viewInsets = FakeViewPadding.zero;
      await tester.pump();
      expect(
        tester.getTopLeft(focusedAnchorMessage).dy,
        closeTo(focusedMessageTopBeforeClose, 0.1),
        reason: 'Focus loss must not move the message sheet.',
      );
      for (var frame = 0; frame < 16; frame += 1) {
        await tester.pump(const Duration(milliseconds: 20));
        final composerBottom = tester.getBottomLeft(composer).dy;
        expect(
          composerBottom,
          greaterThanOrEqualTo(previousComposerBottom - 1),
          reason: 'The composer must move monotonically while losing focus.',
        );
        expect(
          composerBottom,
          lessThanOrEqualTo(composerBottomLimit + 1),
          reason:
              'The keyboard composer must not sink below its final flow bound.',
        );
        if (composerBottom > previousComposerBottom + 1 &&
            composerBottom < composerBottomLimit - 1) {
          sawIntermediateClosingPosition = true;
        }
        previousComposerBottom = composerBottom;
        expect(
          tester.getTopLeft(focusedAnchorMessage).dy,
          closeTo(focusedMessageTopBeforeClose, 0.1),
          reason:
              'Only the composer follows keyboard close; message content '
              'stays at the focused position.',
        );
      }
      expect(
        sawIntermediateClosingPosition,
        isTrue,
        reason:
            'The composer must animate to the zero-keyboard target instead of '
            'jumping there when the inset becomes zero.',
      );
      await tester.pump();
      final roleTitleTopAtKeyboardClosed = tester.getTopLeft(roleTitle).dy;
      final messageTopAtKeyboardClosed = tester
          .getTopLeft(focusedAnchorMessage)
          .dy;
      expect(
        messageTopAtKeyboardClosed,
        closeTo(focusedMessageTopBeforeClose, 0.1),
      );
      for (var frame = 0; frame < 12; frame += 1) {
        await tester.pump();
        expect(
          tester.getBottomLeft(composer).dy,
          lessThanOrEqualTo(composerBottomLimit + 1),
        );
        expect(
          tester.getTopLeft(roleTitle).dy,
          closeTo(roleTitleTopAtKeyboardClosed, 1),
          reason:
              'Restoring the normal scroll extent must not move the visible '
              'role section after the keyboard reaches zero.',
        );
        expect(
          tester.getTopLeft(focusedAnchorMessage).dy,
          closeTo(messageTopAtKeyboardClosed, 1),
          reason:
              'The keyboard-mode handoff must not move the message content a '
              'second time.',
        );
      }
      expect(
        find.byKey(
          const ValueKey<String>('origin-opening-composer-placeholder'),
        ),
        findsNothing,
        reason: 'The composer remains docked instead of switching layouts.',
      );
      expect(
        tester.getBottomLeft(surface).dy - tester.getBottomLeft(composer).dy,
        closeTo(0, 1),
        reason: 'The restored composer stays docked to the sheet bottom.',
      );
      expect(
        find.descendant(
          of: normalOpeningList,
          matching: find.text('Composer docking line 3'),
        ),
        findsOneWidget,
        reason: 'The complete message column stays rendered after focus ends.',
      );
      final restoredCachedRows = find
          .descendant(
            of: normalOpeningList,
            matching: find.byType(ChatMessageRow, skipOffstage: false),
            skipOffstage: false,
          )
          .evaluate()
          .toList(growable: false);
      expect(restoredCachedRows, hasLength(5));
      expect(restoredCachedRows.first, same(warmedRowElements.first));
      expect(restoredCachedRows.last, same(warmedRowElements.last));

      final refocusOpeningPosition = tester
          .state<ScrollableState>(
            find
                .descendant(
                  of: normalOpeningList,
                  matching: find.byType(Scrollable),
                )
                .first,
          )
          .position;
      refocusOpeningPosition.jumpTo(refocusOpeningPosition.maxScrollExtent);
      await tester.pump();
      final refocusBottomMessageTop = tester
          .getTopLeft(focusedAnchorMessage)
          .dy;
      await tester.tap(
        find.descendant(
          of: composer,
          matching: find.byKey(const ValueKey<String>('chat-composer-input')),
        ),
      );
      await tester.pump();
      expect(
        tester.getTopLeft(focusedAnchorMessage).dy,
        closeTo(refocusBottomMessageTop, 0.1),
        reason:
            'Preparing a second keyboard transition at the retained bottom '
            'must not move the message content.',
      );
      _genesisKeyboardAnimationEventSink!.success(const <String, Object>{
        'generation': 2,
        'phase': 'opening',
        'startInset': 0.0,
        'endInset': 300.0,
        'durationMillis': 250.0,
      });
      await tester.pump();
      expect(
        tester.getTopLeft(focusedAnchorMessage).dy,
        closeTo(refocusBottomMessageTop, 0.1),
        reason:
            'Recomputing the opening target must not shrink the retained '
            'scroll range and clamp a bottom-aligned position.',
      );
      tester.view.viewInsets = const FakeViewPadding(bottom: 150);
      await tester.pump();
      tester.view.viewInsets = const FakeViewPadding(bottom: 300);
      for (var frame = 0; frame < 12; frame += 1) {
        await tester.pump();
      }
      final refocusedRows = find.descendant(
        of: normalOpeningList,
        matching: find.byType(ChatMessageRow, skipOffstage: false),
        skipOffstage: false,
      );
      final focusedGapAfterBottomRefocus =
          tester.getTopLeft(composer).dy -
          tester.getBottomLeft(refocusedRows.last).dy;
      expect(
        focusedGapAfterBottomRefocus,
        closeTo(focusedGapFromBottomStart, 1),
        reason:
            'Long content must settle at the same composer gap after '
            'refocusing from the retained list bottom.',
      );
      tester.view.viewInsets = FakeViewPadding.zero;
      for (var frame = 0; frame < 16; frame += 1) {
        await tester.pump(const Duration(milliseconds: 20));
      }
    },
  );

  testWidgets(
    'Origin opening failed launch closes keyboard and restores normal list',
    (WidgetTester tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      tester.view.padding = const FakeViewPadding(bottom: 24);
      tester.view.viewPadding = const FakeViewPadding(bottom: 24);
      addTearDown(tester.view.reset);
      AppStartupCoordinator.resetForTesting();
      addTearDown(AppStartupCoordinator.resetForTesting);
      final originLaunchCompleter = Completer<TransportResponse>();
      final transport = _RecordingV1ListTransport(
        originLaunchCompleter: originLaunchCompleter,
        worldRelationStatus: 'approved',
      );
      await tester.pumpWidget(
        AppServicesScope(
          services: await _testServices(
            transport: transport,
            useMock: false,
            initialAuthToken: 'token',
            initialUserInfo: const {
              'name': 'Nikos',
              'identity': 'Adventure guide',
              'avatar': '',
            },
          ),
          child: MaterialApp(
            onGenerateRoute: AppRouter.onGenerateRoute,
            home: const OriginWorldPage(
              oid: 'o_test_1',
              originId: 0,
              showOpeningSheetOnEntry: true,
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();

      final expandedComposer = find.byKey(
        const ValueKey<String>('origin-expanded-opening-composer'),
      );
      final sharedComposer = find.descendant(
        of: expandedComposer,
        matching: find.byType(LocationChatComposerInput),
      );
      final input = find.descendant(
        of: sharedComposer,
        matching: find.byKey(const ValueKey('chat-composer-input')),
      );
      final editable = find.descendant(
        of: expandedComposer,
        matching: find.byType(EditableText),
      );
      const message = 'Try this opening';
      await tester.enterText(input, message);
      await tester.pump();
      expect(tester.widget<EditableText>(editable).focusNode.hasFocus, isTrue);

      tester.view.viewInsets = const FakeViewPadding(bottom: 150);
      await tester.pump();
      tester.view.viewInsets = const FakeViewPadding(bottom: 300);
      for (var frame = 0; frame < 12; frame += 1) {
        await tester.pump();
      }
      expect(
        find.descendant(
          of: find.byKey(
            const ValueKey<String>('origin-detail-sheet-page-Opening'),
          ),
          matching: find.byType(AbsorbPointer),
        ),
        findsNothing,
        reason:
            'Opening keyboard transitions must not cover the sheet with a '
            'transparent pointer shield.',
      );

      final sendButton = find.descendant(
        of: find.descendant(
          of: sharedComposer,
          matching: find.byKey(const ValueKey('chat-composer-send-button')),
        ),
        matching: find.byType(TextButton),
      );
      await tester.tap(sendButton);
      await _pumpUntilSingleOriginLaunchRequest(tester, transport);
      expect(
        tester.widget<EditableText>(editable).focusNode.hasFocus,
        isTrue,
        reason:
            'The composer keeps focus while the launch request is pending and '
            'dismisses the keyboard only after the request completes.',
      );

      tester.view.viewInsets = FakeViewPadding.zero;
      await tester.pump();

      originLaunchCompleter.complete(
        transport._jsonResponse({
          'err_no': 5000,
          'err_msg': 'Launch rejected',
          'data': <String, Object?>{},
        }),
      );
      for (var frame = 0; frame < 10; frame += 1) {
        await tester.pump();
        if (!tester.widget<EditableText>(editable).focusNode.hasFocus) break;
      }

      expect(find.text('Launch failed'), findsOneWidget);
      expect(tester.widget<EditableText>(editable).focusNode.hasFocus, isFalse);
      expect(
        tester
            .widget<LocationChatComposerInput>(sharedComposer)
            .controller
            .serializedText,
        message,
        reason: 'A failed launch keeps the message available for retry.',
      );

      expect(
        tester
            .widget<PageView>(
              find.byKey(const ValueKey<String>('origin-detail-sheet-pages')),
            )
            .physics,
        isA<PageScrollPhysics>(),
      );
      expect(
        tester
            .widget<IgnorePointer>(
              find.byKey(const ValueKey<String>('origin-opening-role-section')),
            )
            .ignoring,
        isFalse,
      );
      expect(
        tester
            .widget<Opacity>(
              find.byKey(
                const ValueKey<String>(
                  'origin-opening-role-section-settled-visibility',
                ),
              ),
            )
            .opacity,
        1,
      );
      expect(
        find.byKey(
          const ValueKey<String>('origin-opening-keyboard-layout-spacer'),
        ),
        findsNothing,
      );
      expect(
        find.descendant(
          of: find.byKey(
            const ValueKey<String>('origin-detail-sheet-page-Opening'),
          ),
          matching: find.byType(AbsorbPointer),
        ),
        findsNothing,
        reason: 'A failed launch must remove the keyboard transition shield.',
      );
      final openingList = find.descendant(
        of: find.byKey(
          const ValueKey<String>('origin-detail-sheet-page-Opening'),
        ),
        matching: find.byType(CustomScrollView),
      );
      expect(
        tester.widget<CustomScrollView>(openingList).physics,
        isA<ClampingScrollPhysics>(),
      );
      final rolePager = find.descendant(
        of: find.byKey(const ValueKey<String>('origin-opening-role-section')),
        matching: find.byType(PageView),
      );
      final rolePageController = tester.widget<PageView>(rolePager).controller!;
      await tester.drag(rolePager, const Offset(-300, 0));
      await tester.pumpAndSettle();
      expect(
        rolePageController.page,
        greaterThan(0),
        reason: 'The role section must accept gestures after launch failure.',
      );
      final sheetSurface = find.byKey(
        const ValueKey<String>('origin-detail-sheet-surface'),
      );
      expect(
        tester.getBottomLeft(expandedComposer).dy,
        closeTo(tester.getBottomLeft(sheetSurface).dy, 1),
        reason: 'The composer returns to its normal bottom-docked position.',
      );
      await tester.pump(const Duration(seconds: 2));
      await tester.pumpAndSettle();
    },
  );

