      failedOriginLaunchCompleter.complete(
        transport._jsonResponse({
          'err_no': 5000,
          'err_msg': 'launch unavailable',
          'data': <String, Object?>{},
        }),
      );
      for (var frame = 0; frame < 20; frame += 1) {
        await tester.pump();
        final restoredComposer = tester.widget<LocationChatComposerInput>(
          sharedComposer,
        );
        if (!restoredComposer.sending && restoredComposer.inputEnabled) break;
      }
      final restoredComposer = tester.widget<LocationChatComposerInput>(
        sharedComposer,
      );
      expect(restoredComposer.sending, isFalse);
      expect(restoredComposer.inputEnabled, isTrue);
      expect(find.text('Launch failed'), findsOneWidget);
      expect(
        tester
            .widget<EditableText>(
              find.descendant(
                of: expandedComposer,
                matching: find.byType(EditableText),
              ),
            )
            .focusNode
            .hasFocus,
        isFalse,
        reason: 'A failed launch must dismiss the message keyboard.',
      );
      expect(sharedComposerWidget.controller.serializedText, message);
      expect(find.byType(WorldPage), findsNothing);

      tester.view.viewInsets = FakeViewPadding.zero;
      await tester.pump(const Duration(seconds: 2));
      telemetry.events.clear();
      await tester.tap(sharedComposerInput);
      await tester.pump();
      tester.widget<TextButton>(sendButton).onPressed!();
      for (
        var frame = 0;
        frame < 20 && transport.requestsFor('/api/v1/origin/launch').length < 2;
        frame += 1
      ) {
        await tester.pump();
      }
      expect(transport.requestsFor('/api/v1/origin/launch'), hasLength(2));
      _expectOriginLaunchStartTelemetry(
        telemetry: telemetry,
        action: 'worldo_launch_message',
        roleId: 'c_o_test_1',
      );

      originLaunchCompleter.complete(
        transport._jsonResponse({
          'err_no': 0,
          'err_msg': 'succ',
          'data': {'world_id': 'w_launched_from_origin'},
        }),
      );
      for (var frame = 0; frame < 60; frame += 1) {
        await tester.pump();
        if (find.byType(WorldPage).evaluate().isNotEmpty &&
            chatroom.session.sentMessages.isNotEmpty) {
          break;
        }
      }

      _expectOriginLaunchSuccessTelemetry(
        telemetry: telemetry,
        source: 'opening_message',
      );

      final launchedWorldPage = tester.widget<WorldPage>(
        find.byType(WorldPage),
      );
      expect(launchedWorldPage.initialLocationId, 'l_o_test_1');
      expect(launchedWorldPage.initialMessageToSend, message);
      expect(
        launchedWorldPage.initialMentionCatalog?.entryForId('c_o_test_1'),
        isNotNull,
      );
      expect(chatroom.session.sentMessages, [message]);
      expect(chatroom.session.sentUserEnterLocationIds, isEmpty);
      final clientMsgId = chatroom.session.sentClientMsgIds.single;
      chatroom.session.emit(
        ChatroomUserMessage(
          sessionId: 'sess-1',
          worldId: 'w_launched_from_origin',
          locationId: 'l_o_test_1',
          userId: 'u_mock',
          code: 0,
          codeMsg: 'ok',
          ts: null,
          messageId: 43,
          locationMessageId: 43,
          conversationRoundId: 'round-sheet',
          roundOrder: 0,
          senderType: 'user',
          senderId: 'u_mock',
          senderName: 'Me',
          content: message,
          broadcast: true,
          currentTime: '2026-09-01T00:00:00Z',
          clientMsgId: clientMsgId,
          createdAt: null,
        ),
      );
      await tester.pumpAndSettle();
      await tester.pump(const Duration(seconds: 2));
      await tester.pumpAndSettle();
      AppStartupCoordinator.resetForTesting();
    },
  );

