  testWidgets('Me origin and world refresh preserve old list until response', (
    WidgetTester tester,
  ) async {
    final transport = _UserInfoRefreshTransport();
    var walletLoadCount = 0;
    final gemWallet = GemWalletStore(
      loadWallet: () async {
        walletLoadCount += 1;
        return GemWallet(balanceCent: 44000 - walletLoadCount * 1000);
      },
      readUid: () async => 'u_me_refresh',
    );
    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(
          body: AppServicesScope(
            services: await _testServices(
              transport: transport,
              useMock: false,
              initialUid: 'u_me_refresh',
              initialAuthToken: 'backend-token',
              gemWallet: gemWallet,
            ),
            child: const MePage(),
          ),
        ),
      ),
    );
    await tester.pumpAndSettle();

    expect(find.text('#Origin Old'), findsOneWidget);
    expect(find.text('#Origin New'), findsNothing);
    expect(walletLoadCount, 1);
    expect(find.text('430.0'), findsOneWidget);

    final pageRefresh = find.descendant(
      of: find.byKey(const ValueKey('profile-page-refresh')),
      matching: find.byType(RefreshIndicator),
    );
    var refreshFuture = tester
        .widget<RefreshIndicator>(pageRefresh)
        .onRefresh();
    await tester.pump();

    expect(transport.originListRequests, 2);
    expect(walletLoadCount, 2);
    expect(find.text('#Origin Old'), findsOneWidget);
    expect(find.text('#Origin New'), findsNothing);

    transport.completeOriginRefresh();
    await tester.pumpAndSettle();
    await refreshFuture;

    expect(find.text('#Origin Old'), findsNothing);
    expect(find.text('#Origin New'), findsOneWidget);
    expect(find.text('420.0'), findsOneWidget);

    await tester.tap(find.text('Playing'));
    await tester.pumpAndSettle();

    expect(find.text('World Old'), findsOneWidget);
    expect(find.text('World New'), findsNothing);

    refreshFuture = tester.widget<RefreshIndicator>(pageRefresh).onRefresh();
    await tester.pump();

    expect(transport.worldListRequests, 3);
    expect(walletLoadCount, 3);
    expect(find.text('World Old'), findsOneWidget);
    expect(find.text('World New'), findsNothing);

    transport.completeWorldRefresh();
    await tester.pumpAndSettle();
    await refreshFuture;

    expect(find.text('World Old'), findsNothing);
    expect(find.text('World New'), findsOneWidget);
    expect(find.text('410.0'), findsOneWidget);
  });

  testWidgets('Me pull gesture refreshes from the whole profile top', (
    WidgetTester tester,
  ) async {
    final transport = _UserInfoRefreshTransport(initialItemCount: 8);
    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(
          body: AppServicesScope(
            services: await _testServices(
              transport: transport,
              useMock: false,
              initialUid: 'u_me_refresh',
              initialAuthToken: 'backend-token',
            ),
            child: const MePage(),
          ),
        ),
      ),
    );
    await tester.pumpAndSettle();

    expect(transport.originListRequests, 1);
    final pageScroll = find.byType(NestedScrollView);
    final nestedScroll = tester.state<NestedScrollViewState>(pageScroll);
    final scrollable = nestedScroll.outerController;

    await tester.drag(pageScroll, const Offset(0, -180));
    await tester.pumpAndSettle();
    expect(scrollable.position.pixels, greaterThan(0));

    var gesture = await tester.startGesture(tester.getCenter(pageScroll));
    await gesture.moveBy(const Offset(0, 40));
    await tester.pump();
    scrollable.position.jumpTo(0);
    await tester.pump();
    await gesture.moveBy(const Offset(0, 300));
    await tester.pump();
    await gesture.up();
    await tester.pumpAndSettle();

    expect(scrollable.position.pixels, closeTo(0, 0.5));
    expect(transport.originListRequests, 1);

    gesture = await tester.startGesture(tester.getCenter(pageScroll));
    final profileHeader = find.byKey(
      const ValueKey<String>('user-profile-follow-stats'),
    );
    final profileHeaderTopBefore = tester.getTopLeft(profileHeader).dy;
    await gesture.moveBy(const Offset(0, 20));
    await tester.pump();
    await gesture.moveBy(const Offset(0, 180));
    await tester.pump();
    expect(
      tester.getTopLeft(profileHeader).dy,
      greaterThan(profileHeaderTopBefore),
    );
    await gesture.moveBy(const Offset(0, 320));
    await tester.pump();
    await gesture.up();
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 300));
    await tester.pump();

    expect(transport.originListRequests, 2);
    transport.completeOriginRefresh();
    await tester.pumpAndSettle();
    expect(find.text('#Origin New'), findsOneWidget);
  });

  testWidgets('Me collection tabs still switch with horizontal swipes', (
    WidgetTester tester,
  ) async {
    final transport = _UserInfoRefreshTransport();
    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(
          body: AppServicesScope(
