  testWidgets('world detail sheet pauses Tilemap animations while open', (
    WidgetTester tester,
  ) async {
    final transport = _RecordingV1ListTransport(
      worldRelationStatus: 'anonymous',
      worldDefinitionVersion: 2,
    );
    await tester.pumpWidget(
      AppServicesScope(
        services: await _testServices(transport: transport, useMock: false),
        child: const MaterialApp(home: WorldPage(wid: 'w_test_1')),
      ),
    );
    await tester.pumpAndSettle();

    Tilemap currentTilemap() => tester.widget<Tilemap>(find.byType(Tilemap));
    expect(currentTilemap().animationsPaused, isFalse);

    final detailTag = find.descendant(
      of: find.byKey(const ValueKey<String>('world-bottom-tags-overlay')),
      matching: find.text('Detail'),
    );
    await tester.tap(detailTag);
    await tester.pumpAndSettle();
    expect(currentTilemap().animationsPaused, isTrue);
    final openedSheet = find.byKey(
      const ValueKey<String>('world-single-section-bottom-sheet'),
    );
    final openedSheetContext = tester.element(openedSheet);
    expect(
      tester.getTopLeft(openedSheet).dy,
      closeTo(
        GenesisSafeAreaInsets.top(openedSheetContext) +
            worldDetailSheetExpandedTopOffset,
        1,
      ),
    );
    final draggableSheet = tester.widget<DraggableScrollableSheet>(
      find.ancestor(
        of: openedSheet,
        matching: find.byType(DraggableScrollableSheet),
      ),
    );
    expect(draggableSheet.snap, isFalse);

    final sheetIndicator = find.byKey(
      const ValueKey<String>('world-sheet-page-indicator'),
    );
    expect(sheetIndicator, findsOneWidget);
    expect(tester.getSize(sheetIndicator), const Size(53, 4));
    expect(
      tester.getTopLeft(sheetIndicator).dy - tester.getTopLeft(openedSheet).dy,
      closeTo(8.5, 0.001),
    );
    expect(
      find.descendant(
        of: openedSheet,
        matching: find.byIcon(Icons.close_rounded),
      ),
      findsOneWidget,
    );
    for (var index = 0; index < 4; index++) {
      final segment = find.byKey(
        ValueKey<String>('world-sheet-page-segment-$index'),
      );
      expect(segment, findsOneWidget);
      expect(tester.getSize(segment).height, 4);
      expect(tester.getSize(segment).width, index == 0 ? 26 : 4);
      expect(
        (tester.widget<Container>(segment).decoration as BoxDecoration).color,
        index == 0 ? const Color(0xFF666666) : const Color(0xFFB7B7B7),
      );
    }

    final sheetPages = find.descendant(
      of: find.byKey(
        const ValueKey<String>('world-single-section-bottom-sheet'),
      ),
      matching: find.byType(PageView),
    );
    expect(sheetPages, findsOneWidget);
    final sheetPageController = tester.widget<PageView>(sheetPages).controller!;
    final pageAnimation = sheetPageController.animateToPage(
      1,
      duration: const Duration(milliseconds: 220),
      curve: Curves.easeOutCubic,
    );
    await tester.pumpAndSettle();
    await pageAnimation;
    expect(
      tester
          .getSize(
            find.byKey(const ValueKey<String>('world-sheet-page-segment-0')),
          )
          .width,
      4,
    );
    expect(
      tester
          .getSize(
            find.byKey(const ValueKey<String>('world-sheet-page-segment-1')),
          )
          .width,
      26,
    );

    final returnToDetail = sheetPageController.animateToPage(
      0,
      duration: const Duration(milliseconds: 220),
      curve: Curves.easeOutCubic,
    );
    await tester.pumpAndSettle();
    await returnToDetail;
    final sheet = find.byKey(
      const ValueKey<String>('world-single-section-bottom-sheet'),
    );
    final detailList = find
        .descendant(of: sheet, matching: find.byType(ListView))
        .hitTestable()
        .first;
    final settleBackGesture = await tester.startGesture(
      tester.getCenter(detailList),
    );
    await settleBackGesture.moveBy(const Offset(0, 20));
    await tester.pump();
    await settleBackGesture.moveBy(const Offset(0, 180));
    await tester.pump(const Duration(seconds: 1));
    await settleBackGesture.up();
    await tester.pumpAndSettle();
    expect(
      tester.getTopLeft(sheet).dy,
      closeTo(
        GenesisSafeAreaInsets.top(openedSheetContext) +
            worldDetailSheetExpandedTopOffset,
        1,
      ),
    );
    await tester.fling(detailList, const Offset(0, 150), 3000);
    await tester.pump(const Duration(milliseconds: 100));
    expect(sheet, findsOneWidget);
    await tester.pumpAndSettle();
    expect(sheet, findsNothing);
    expect(currentTilemap().animationsPaused, isFalse);

    await tester.tap(detailTag);
    await tester.pumpAndSettle();
    final reopenedDraggableSheet = tester.widget<DraggableScrollableSheet>(
      find.ancestor(of: sheet, matching: find.byType(DraggableScrollableSheet)),
    );
    final collapseGesture = await tester.startGesture(
      tester.getCenter(detailList),
    );
    await collapseGesture.moveBy(const Offset(0, 20));
    await tester.pump();
    final collapseTargetExtent =
        (reopenedDraggableSheet.minChildSize + 0.5) / 2;
    final draggableHostHeight = tester
        .getSize(find.byType(DraggableScrollableSheet))
        .height;
    await collapseGesture.moveBy(
      Offset(
        0,
        (reopenedDraggableSheet.controller!.size - collapseTargetExtent) *
            draggableHostHeight,
      ),
    );
    await tester.pump();
    expect(reopenedDraggableSheet.controller!.size, lessThan(0.5));
    await collapseGesture.up();
    await tester.pump(const Duration(milliseconds: 100));
    expect(sheet, findsOneWidget);
    await tester.pumpAndSettle();
    expect(
      find.byKey(const ValueKey<String>('world-single-section-bottom-sheet')),
      findsNothing,
    );
    expect(currentTilemap().animationsPaused, isFalse);

    for (final sectionLabel in const ['Locations', 'Events', 'Status']) {
      final sectionTag = find.descendant(
        of: find.byKey(const ValueKey<String>('world-bottom-tags-overlay')),
        matching: find.text(sectionLabel),
      );
      await tester.tap(sectionTag);
      await tester.pumpAndSettle();

      final sectionSheet = find.byKey(
        const ValueKey<String>('world-single-section-bottom-sheet'),
      );
      expect(sectionSheet, findsOneWidget);
      final verticalScrollable = find
          .descendant(
            of: sectionSheet,
            matching: find.byWidgetPredicate(
              (widget) =>
                  widget is Scrollable &&
                  axisDirectionToAxis(widget.axisDirection) == Axis.vertical,
            ),
          )
          .hitTestable()
          .last;
      await tester.drag(verticalScrollable, const Offset(0, 500));
      await tester.pumpAndSettle();
      expect(sectionSheet, findsNothing);
    }

    await tester.tap(detailTag);
    await tester.pumpAndSettle();
    final headerDraggedSheet = find.byKey(
      const ValueKey<String>('world-single-section-bottom-sheet'),
    );
    await tester.drag(
      find.byKey(const ValueKey<String>('world-sheet-header-drag-area')),
      const Offset(0, 500),
    );
    await tester.pumpAndSettle();
    expect(headerDraggedSheet, findsNothing);
  });

  testWidgets('world route shows its real shell during initial Android push', (
    WidgetTester tester,
  ) async {
    const viewportSize = Size(400, 800);
    tester.view.physicalSize = viewportSize;
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final worldDetailCompleter = Completer<TransportResponse>();
    final transport = _RecordingV1ListTransport(
      worldDetailCompleter: worldDetailCompleter,
    );
    final services = await _testServices(transport: transport, useMock: false);

    await tester.pumpWidget(
      AppServicesScope(
        services: services,
        child: MaterialApp(
          theme: ThemeData(platform: TargetPlatform.android),
          onGenerateRoute: AppRouter.onGenerateRoute,
          home: Scaffold(
            body: Builder(
              builder: (context) => TextButton(
                onPressed: () => Navigator.of(context).pushNamed(
                  RouteNames.world,
                  arguments: const <String, Object?>{
                    'wid': 'w_test_1',
                    'initiallyLaunched': true,
                  },
                ),
                child: const Text('Open World'),
              ),
            ),
          ),
        ),
      ),
    );

    await tester.tap(find.text('Open World'));
    await tester.pump();
    await tester.pump();

    final mapBackground = find.byKey(
      const ValueKey<String>('world-map-loading-background'),
    );
    expect(
      find.byKey(const ValueKey<String>('world-route-transition-background')),
      findsNothing,
    );
    expect(
      find.byKey(const ValueKey<String>('world-route-opaque-slide-transition')),
      findsNothing,
    );
    expect(
      tester
          .getSize(find.byKey(const ValueKey<String>('world-panel-info-row')))
          .height,
      worldLaunchedInfoHeaderHeight,
    );

    expect(mapBackground, findsOneWidget);
    final worldRoute = ModalRoute.of(tester.element(find.byType(WorldPage)))!;
    final routeAnimation = worldRoute.animation!;
    expect(worldRoute.transitionDuration, greaterThan(Duration.zero));
    expect(routeAnimation.value, 0);

    final pageScaffold = find.descendant(
      of: find.byType(WorldDetailsPageScaffold),
      matching: find.byType(Scaffold),
    );
    final initialPageRect = tester.getRect(pageScaffold);
    final initialPanelRect = tester.getRect(
      find.byKey(const ValueKey<String>('world-panel-info-row')),
    );
    expect(initialPageRect.left, 0);

    await tester.pump(
      Duration(microseconds: worldRoute.transitionDuration.inMicroseconds ~/ 2),
    );

    expect(routeAnimation.value, greaterThan(0));
    expect(routeAnimation.value, lessThan(1));
    final midTransitionPageRect = tester.getRect(pageScaffold);
    final midTransitionPanelRect = tester.getRect(
      find.byKey(const ValueKey<String>('world-panel-info-row')),
    );
    expect(midTransitionPageRect, initialPageRect);
    expect(midTransitionPanelRect, initialPanelRect);

    await tester.pump(worldRoute.transitionDuration);

    expect(routeAnimation.value, 1);
    expect(tester.getRect(pageScaffold), initialPageRect);
    expect(
      tester.getRect(
        find.byKey(const ValueKey<String>('world-panel-info-row')),
      ),
      initialPanelRect,
    );

    await tester.pumpWidget(const SizedBox.shrink());
    worldDetailCompleter.complete(transport._jsonResponse({}));
    await tester.pump();
  });

