        'world_name': 'World One',
        'location_id': 'castle',
        'location_name': 'Castle',
      },
    );
    await tester.pump(const Duration(milliseconds: 300));

    for (var i = 1; i <= 60; i += 1) {
      chatroom.session.emit(
        ChatroomUserMessage(
          sessionId: 'sess-1',
          worldId: 'world-1',
          locationId: 'castle',
          userId: 'u_peer',
          code: 0,
