        ts: null,
        messageId: 61,
        locationMessageId: 61,
        conversationRoundId: '61',
        roundOrder: 0,
        senderType: 'user',
        senderId: 'u_peer',
        senderName: 'Peer',
        content: 'focused new message',
        broadcast: true,
        currentTime: '2026-06-25T00:00:00Z',
        clientMsgId: '',
        createdAt: null,
      ),
    );
    await tester.pump();
    await tester.pump();

    expect(position.pixels, closeTo(position.maxScrollExtent, 1));
    expect(find.text('1 new message'), findsNothing);

    await tester.drag(scrollable, const Offset(0, 300));
    await tester.pump();
    final offsetAfterUserDrag = position.pixels;
    expect(offsetAfterUserDrag, lessThan(position.maxScrollExtent));

    chatroom.session.emit(
      ChatroomUserMessage(
        sessionId: 'sess-1',
        worldId: 'world-1',
        locationId: 'castle',
        userId: 'u_peer',
        code: 0,
        codeMsg: 'ok',
        ts: null,
        messageId: 62,
        locationMessageId: 62,
        conversationRoundId: '62',
        roundOrder: 0,
        senderType: 'user',
        senderId: 'u_peer',
        senderName: 'Peer',
        content: 'focused but user is reading',
        broadcast: true,
        currentTime: '2026-06-25T00:00:00Z',
        clientMsgId: '',
        createdAt: null,
      ),
    );
    await tester.pump(const Duration(milliseconds: 300));

    expect(position.pixels, lessThan(position.maxScrollExtent));
    expect(find.text('1 new message'), findsOneWidget);
  });

